shell_commands:
/bin/zsh -lc "cat >> specs/hal-engine-tool-input-validation/spec.md <<'EOF'

- An explicitly disallowed additional property is identified by its property path ([validated by: reports the path of a disallowed additional property](../../src/orchestration/tools/registry.additional-property.test.ts#L4)).
EOF
cat > src/orchestration/tools/registry.additional-property.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#15
it('reports the path of a disallowed additional property', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object', additionalProperties: false}},
    async () => 'sunny'
  );
  const response = await registry.execute('weather', {unexpected: 'private-value'});
  expect(response.result).toMatch(/\\/unexpected.*additionalProperties/);
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registry.additional-property.test.ts --runInBand"
